  str_aircraft_tactic_mission_name_10_10_3 = "Showdown Simulation 10 (Sulit)",
  str_aircraft_tactic_info11101 = "Gold River: Sungai yang berasal dari World's Spine ini adalah yang terpanjang di seluruh Astra. Airnya berasal dari lelehan salju yang menutupi pegunungan asal dan kelok sungainya membelah seantero benua.",
  str_aircraft_tactic_info11102 = "Mata Pencaharian di Sepanjang Gold River: Kemakmuran desa-desa yang memadati lembah Gold River berasal dari aliran sungai dan tepiannya yang subur. Di sepanjang aliran utama sungai, barisan pedesaan maju mengandalkan komunikasi canggih dan perdagangan yang kuat demi meningkatkan kondisi permukiman mereka.",
  str_aircraft_tactic_info11103 = "Kuliner di Desa: Para penduduk desa di sepanjang Gold River sering menyantap makanan yang jumlahnya melimpah dan mudah didapat, yakni kacang polong serta beragam olahannya, ikan asin, dan daging hewan.",
  str_aircraft_tactic_info11104 = "Perdagangan: Banyak pedagang Gold River bekerja di sepanjang rute perdagangan yang ditetapkan secara ketat. Mereka menjajakan barang dagangan ke kota-kota makmur yang berjajar di tepiannya.",
  str_aircraft_tactic_info11201 = "Gold River: Gold River yang seakan tak berujung membentang melintasi daratan dari langit, mengalir dari barat laut ke tenggara sebelum akhirnya bermuara ke laut.",
  str_aircraft_tactic_info11202 = "Mata Pencaharian di Sepanjang Gold River: Pedesaan di sekitar anak sungai Gold River masih menganut cara hidup yang lebih tradisional. Para penduduk desa hidup dengan menangkap ikan atau mengairi kebun mereka dengan air sungai.",
  str_aircraft_tactic_info11203 = "Kuliner di Desa: Para penduduk desa juga menanam gandum sampai batas tertentu, tetapi jarang dimanfaatkan sebagai makanan pokok. Gandum itu justru digunakan untuk membuat bir, minuman yang tak tergantikan bagi banyak warga setempat.",
  str_aircraft_tactic_info11204 = "Perdagangan: Ketika dihadapkan dengan kesempatan yang unik, beberapa pedagang mungkin bersedia membuka rute perdagangan baru di seluruh negeri. Tentu saja, mengingat keadaan dunia yang asing dan berisiko, mereka hampir selalu dikawal oleh penjaga bersenjata.",
  str_aircraft_tactic_info11301 = "Luminatics: Tidak semua Aurorian terlahir dengan kemampuan untuk menggunakan Luminatics. Kemampuan ini lebih seperti potensi yang menunggu untuk dibangkitkan.",
  str_aircraft_tactic_info11302 = "Ransum Lumopolis: Makanan yang menjadi ransum standar untuk tentara Lumopolis ini terbuat dari roti putih yang diperkaya dengan garam dan gula yang sesuai dan dicampur dengan Luminatics.",
  str_aircraft_tactic_info11303 = "Zirah Pelat: Zirah badan yang dikenakan oleh para kesatria dan disediakan oleh gereja. Sebagian besar kesatria dibekali dengan zirah pelat yang berat tetapi lebih tahan serangan. Sementara itu, kesatria tertentu yang lebih menyukai mobilitas ketimbang pertahanan lebih memilih mengenakan zirah rantai.",
  str_aircraft_tactic_info11304 = "Perisai Menara: Peralatan Lumo Knight yang ikonis dan tak tergantikan ini mewakili afiliasi dengan jajaran kesatria Lumopolis. Bentuk dan ukuran perisainya mungkin sedikit berbeda tergantung pada prajurit yang menggunakannya, tetapi lambang yang ada di permukaannya tetap tidak berubah.",
  str_aircraft_tactic_info11401 = "Luminatics: Ada berbagai penyebab yang bisa memicu kebangkitannya. Contohnya adalah bimbingan dari orang tertentu atau momen penting dalam sejarah seseorang… Meskipun banyak Aurorian menjalani seluruh hidup mereka tanpa menggunakan Luminatics, cahaya matahari tetap menyinari mereka semua dengan setara.",
  str_aircraft_tactic_info11402 = "Ransum Lumopolis: Ransum ini tidak hanya memiliki umur simpan yang lebih lama, tetapi rasanya juga lebih enak. Ringan, mudah dibawa, dan keseimbangan antara rasa manis dan asinnya luar biasa. Meskipun ransum militer ini ditujukan untuk memuaskan rasa lapar, kualitasnya masih lebih baik dari kebanyakan makanan yang tersedia untuk rakyat jelata.",
  str_aircraft_tactic_info11403 = "Zirah Pelat: Beberapa kesatria akan memilih zirah yang dibuat secara khusus. Dalam situasi pertempuran tertentu, bahkan ada kesatria yang akan memilih untuk memakai berbagai jenis zirah sekaligus.",
  str_aircraft_tactic_info11404 = "Perisai Menara: Gereja akan menghadiahkan perisai kepada para kesatria pada hari mereka dilantik ke dalam ordo sebagai perlambang keyakinan Lumopolis bahwa perlindungan jauh lebih penting dari penaklukan. Perisai dipandang lebih kuat dari pedang dan identik dengan kekesatriaan dan kewajibannya.",
  str_aircraft_tactic_info11501 = "Courier Union: Sebuah organisasi layanan pos yang telah berdiri selama berabad-abad. Meskipun jumlah anggotanya sedikit, organisasi ini menuai pujian luas di seluruh Astra atas pengirimannya yang sangat cepat dan efisien.",
  str_aircraft_tactic_info11502 = "Post: Fasilitas khusus untuk Courier Union ini berfungsi sebagai tempat peristirahatan bagi para kurirnya dan menyediakan makanan serta perbekalan lain yang diperlukan dalam perjalanan mereka. Orang-orang yang ingin mengirim surat bisa menyerahkannya ke sini juga.",
  str_aircraft_tactic_info11503 = "Buku Rencana Perjalanan: Buku catatan ini mencatat perjalanan kurir saat melakukan pengiriman.",
  str_aircraft_tactic_info11504 = "Dandelion: Bunga spesial yang melambangkan Eraveil ini dicintai oleh semua Caelestite karena tampilannya yang putih dan halus, serta nilai kebebasan tanpa batas yang dilambangkannya.",
  str_aircraft_tactic_info11601 = "Courier Union: Courier Union sering dikontrak untuk pengiriman jarak jauh melintasi perbatasan, terkadang melalui rute berbahaya yang tertutup untuk umum.",
  str_aircraft_tactic_info11602 = "Post: Ada juga kotak surat di pintu masuk Post ini. Surat yang hendak dikirim dapat dimasukkan ke dalam kotak surat itu untuk kemudian diterima dan diantarkan oleh kurir berikutnya yang tiba di Post.",
  str_aircraft_tactic_info11603 = "Buku Rencana Perjalanan: Para kurir mencatat surat-surat yang telah mereka kirimkan atau sedang dikirimkan, Post tempat mereka berhenti untuk beristirahat, dan seterusnya. Bisa dibilang ini adalah barang pribadi yang paling penting bagi setiap kurir.",
  str_aircraft_tactic_info11604 = "Dandelion: Terlepas dari jumlahnya yang melimpah di Eraveil, kaum Caelestite gemar membuat objek dan hiasan yang menyerupai bunga ini saat hari raya.",
  str_aircraft_tactic_info11701 = "Azurite: Sebuah pulau terapung besar yang melayang di atas Dataran Astra. Bertahun-tahun lalu, para Aurorian di utara nun jauh berjuang menaklukkan lingkungan tanah air mereka yang tidak ramah dan ancaman Eclipsite yang selalu ada. Setelah meninggalkan rumah, mereka tiba di Astra dan akhirnya menemukan cara untuk mendaki puncak Azurite.",
  str_aircraft_tactic_info11702 = "Shuttle Hub: Shuttle Hub di Lower Lumopolis adalah satu-satunya pelabuhan masuk untuk seluruh kota. Semua airship yang bepergian masuk dan keluar dari Lumopolis harus melewati tempat ini dan harus menjalani pemeriksaan ketat terlepas dari arah perjalanannya. Dalam banyak kasus, surat permohonan harus dibuat jauh-jauh hari sebelumnya untuk melewati pelabuhan ini.",
  str_aircraft_tactic_info11703 = "Umbraton dan Azurite: Sebagai negara kota yang paling dekat dengan Azurite, Umbraton adalah penghubung alami antara Lumopolis dan dunia luar.",
  str_aircraft_tactic_info11704 = "Airship: Sarana transportasi utama dari dan menuju Lumopolis. Bergantung pada lokasi pembuatannya, airship yang berbeda tidak hanya memiliki penampilan yang berbeda, tetapi sistem daya dorongnya juga berbeda. Contoh dari perbedaan ini adalah airship yang diciptakan di Illumina dirancang dengan desain bergaya industri dan digerakkan oleh panas. Airship Lumopolis, di sisi lain, lebih fokus pada keindahan dan keanggunan luar dan ditenagai oleh Lumina.",
  str_aircraft_tactic_info11801 = "Azurite: Aurorian membentuk masyarakat yang menempatkan para bangsawan sebagai pemegang peranan penting, sebuah tatanan sosial yang didasarkan pada sistem kekaisaran kuno. Demikianlah pulau Azurite berubah menjadi Lumopolis—kota agung yang terapung di langit.",
  str_aircraft_tactic_info11802 = "Shuttle Hub: Shuttle Hub dibagi menjadi empat sektor, masing-masing dengan jenis lalu lintas yang ditentukan: pariwisata, logistik, militer, dan khusus.",
  str_aircraft_tactic_info11803 = "Umbraton dan Azurite: Pelabuhan airship untuk masuk dan keluar Lumopolis telah didirikan di sini di bawah pemerintahan tunggal Lumopolis. Dalam sebagian besar kasus, seseorang harus melewati Umbraton untuk memasuki Azurite.",
  str_aircraft_tactic_info11804 = "Airship: Pelabuhan Umbraton dan Lumopolis menyediakan airship sebagai sarana transportasi umum bagi warganya. Beberapa warga negara terkemuka dan kaya bahkan memiliki airship pribadi.",
  str_aircraft_tactic_info11901 = "Lencana Kurir: Lencana yang permukaannya diukir dengan pena bulu. Hadiah berharga yang membuktikan identitas pemakainya sebagai anggota Courier Union ini biasanya terlihat tergantung di buku rencana perjalanan seorang kurir.",
  str_aircraft_tactic_info11902 = "Lower Lumopolis: Pusat produksi pertanian dan industri kota. Meskipun ruang perumahannya relatif kecil, kepadatan penduduknya mencatatkan angka tertinggi di seantero Lumopolis.",
  str_aircraft_tactic_info11903 = "Di dalam Shuttle Hub: Pusat aktivitas komersial paling semarak dan ramai di seluruh Lumopolis. Di sini, kamu bisa menjumpai segala macam orang—pedagang dan bangsawan yang menunggu airship, juga turis dengan dompet koin yang berat.",
  str_aircraft_tactic_info11904 = "Komoditas Lumopolis: Barang-barang di Lumopolis umumnya termasuk perhiasan emas dan perak, batu permata berharga, dan bulu yang indah. Pokoknya, sebagian besar berupa barang-barang mewah.",
  str_aircraft_tactic_info12001 = "Lencana Kurir: Ada beberapa lencana cadangan di setiap Post untuk berjaga-jaga jika seorang kurir yang linglung kehilangan lencananya.",
  str_aircraft_tactic_info12002 = "Lower Lumopolis: Ini adalah rumah bagi bangsawan kelas bawah, serta para pelayan bangsawan kelas menengah dan atas. Di sinilah perkotaan dan pedesaan melebur, terutama jika dibandingkan dengan Lumopolis Garden atau Lumopolis Courtyard.",
  str_aircraft_tactic_info12003 = "Shuttle Hub: Para pedagang bermata tajam telah menemukan peluang di hub. Mereka menjajakan segala sesuatu mulai dari barang mewah hingga makanan khas setempat.",
  str_aircraft_tactic_info12004 = "Komoditas Lumopolis: Barang impor yang langka dan eksotis juga bisa ditemukan di sini, seperti rempah-rempah dan bahan-bahan dari negeri yang jauh.",
  str_aircraft_tactic_info12101 = "Tanggung Jawab Lumo Knight: Berafiliasi dengan cabang militer Lumopolis, tujuan utama Lumo Knight adalah untuk menangkis serangan high-level Eclipsite dan mencari sisa-sisa peradaban kuno.",
  str_aircraft_tactic_info12102 = "Permukiman Kumuh Lower Lumopolis: Permukiman kumuh di Lower Lumopolis merupakan aib yang menodai kemegahan kota. Di sana, sebagian besar bangunan batunya yang bobrok telah ditinggalkan dan jalanannya berwarna abu-abu serta dipenuhi sampah akibat kurangnya perawatan rutin. Penduduk permukiman kumuh mengenakan pakaian tipis apa pun yang bisa mereka temukan.",
  str_aircraft_tactic_info12103 = "Peace Officer: Guard dipercaya untuk menjaga hukum dan ketertiban di Lumopolis, serta melindungi Keluarga Schwartz.",
  str_aircraft_tactic_info12104 = "Kehidupan Warga Lumopolis: Mayoritas warga kota terpusat di Lower Lumopolis. Di sana, mereka tidak hanya pergi bekerja, tetapi juga menghabiskan waktu di bar, kafe, toko, dan teaternya.",
  str_aircraft_tactic_info12201 = "Tanggung Jawab Lumo Knight: Dalam keadaan normal, tugas sehari-hari mereka juga mencakup menjaga hukum dan ketertiban di kota.",
  str_aircraft_tactic_info12202 = "Permukiman Kumuh Lower Lumopolis: Meskipun hampir tidak ada hukum dan ketertiban di tempat ini, keputusasaan mencegah sebagian besar kerusuhan. Bahkan sepertinya sinar matahari pun telah berpaling dari sektor kota ini, membiarkannya menggigil dan membusuk dalam kegelapan.",
  str_aircraft_tactic_info12203 = "Peace Officer: Guard dibagi menjadi beberapa kelompok kecil dan tiap-tiap kelompok itu ditugaskan untuk menjaga wilayah kota yang berbeda. Misalnya, regu yang ditugaskan untuk melindungi Lumopolis Garden dikenal sebagai Lumo Gardens Guard. Begitu pula dengan regu yang ditugaskan untuk menjaga perdamaian dan ketertiban umum. Mereka dikenal sebagai Peace Officer.",
  str_aircraft_tactic_info12204 = "Kehidupan Penduduk Lumopolis: Sebagian besar penduduk tidak bercita-cita menjadi bangsawan. Mereka lebih suka menikmati hiburan yang lebih sederhana dan lebih murah.",
  str_aircraft_tactic_info12301 = "Darkover Crisis: Darkover Crisis bermula tujuh belas tahun yang lalu ketika organisasi yang dikenal sebagai Eclipse berusaha untuk menangkap Colossus, mesin terbang raksasa nan canggih dari peradaban yang telah lama hilang. Dengan bantuan pasukan Eclipsite, mereka mengepung Eraveil, rumah ras Caelestite. Akibatnya, hanya sedikit yang selamat dari pembantaian itu. Namun, tujuh tahun kemudian, pasukan Eclipsite berhasil dikalahkan oleh kekuatan militer gabungan Astra, dan Darkover Crisis pun berakhir.",
  str_aircraft_tactic_info12302 = "Patung Queen Bethlehem: Penduduk Northland mencintai ratu mereka dengan tulus. Mengingat kehidupan di utara berjalan relatif lambat, para Aurorian di Northland yang cekatan menghabiskan banyak waktu luang mereka untuk mengukir berbagai kerajinan kayu. Ukiran yang menyerupai sosok Queen Bethlehem adalah yang paling umum.",
  str_aircraft_tactic_info12303 = "Lumowhistler: Permen sederhana yang banyak disukai oleh anak kecil ini bisa mengeluarkan suara siulan saat ditiup. Bagi kebanyakan Aurorian, permen ini membuat mereka bernostalgia. Bahkan orang dewasa pun terkadang membelinya untuk mengingat kenangan masa kecil mereka.",
  str_aircraft_tactic_info12304 = "Crunchy Munchy Crunch: Camilan khas yang terkenal dari wilayah gurun Astra. Penampilannya mungkin sedikit mengecewakan bagi orang awam, tetapi di situlah letak daya tariknya. Terbuat dari kadal kecil yang telah digoreng dan dikeringkan hingga garing, mereka benar-benar mempertahankan bentuk dan postur asli kadal hidup. Meski agak mengerikan, mungkin ini bagian dari selera humor orang gurun, 'kan?",
  str_aircraft_tactic_pic_name1 = "Journey's Dawn",
  str_aircraft_tactic_pic_name2 = "Snowland Ballad",
  str_aircraft_tactic_pic_name3 = "Rosa and M&M's Correspondence",
  str_aircraft_tactic_pic_name4 = "Mrs. Red Mercury",
  str_aircraft_tactic_locked_condition = "Buka 4 petunjuk untuk mendapatkannya!",
  str_aircraft_tactic_info21101 = "Elder: Lord dan Elder ditunjuk untuk memerintah desa dan kota kecil dan, dalam beberapa kasus, penduduk desa mengatur desa mereka secara swadaya. Namun, semua desa dan kota harus mematuhi peraturan keluarga kerajaan Northland mengenai hal-hal besar.",
  str_aircraft_tactic_info21102 = "Ikan Haring Kalengan: Makanan unik dari Northland yang bisa disimpan dalam kurun waktu yang lama. Makanan ini sangat populer di kalangan penduduk setempat, tetapi orang luar umumnya menganggap aroma dan rasanya terlalu kuat.",
  str_aircraft_tactic_info21103 = "Permen Karet: Northland merupakan habitat banyak varietas tanaman beri liar dan permen karet lembut buatan mereka adalah kesukaan anak-anak di seluruh negeri.",
  str_aircraft_tactic_info21104 = "Daging Hiu Fermentasi: Untuk alasan yang tak diketahui, hiu telah bermutasi dan muncul di perairan Northland yang dingin. Setelah melalui proses fermentasi khusus, daging hiu bisa dimakan dengan aman.",
  str_aircraft_tactic_info22101 = "Pondok Jerami: Sebuah bangunan yang digunakan untuk menyimpan biji-bijian dan kayu. Meskipun bentuknya sederhana, bangunan ini relatif tahan angin.",
  str_aircraft_tactic_info22102 = "Migrasi Penduduk Northland: Banyak anak muda Northland meninggalkan negeri yang dingin dan terbelakang ini untuk menjelajah ke dunia luar. Namun, pesona unik utara selalu berhasil membawa anak-anak muda ini pulang. Sering kali kita bisa melihat sesosok pengelana yang pulang ke rumah di jalan menuju Northland.",
  str_aircraft_tactic_info22103 = "Iklim Unik Northland: Sebagian besar Northland ditutupi oleh es dan salju yang tetap beku sepanjang tahun. Hanya beberapa tempat yang memiliki iklim sedang, dengan aroma samar awal musim semi yang tertinggal di salju.",
  str_aircraft_tactic_info22104 = "Pegunungan di Northland: Northland terletak di World's Spine—pegunungan tertinggi di benua itu. Konon kita bisa mencapai Land of Eternal Night melalui gunung ini, tetapi kabar ini tetap menjadi legenda. Penduduk Northland jarang melakukan perjalanan jauh ke World's Spine karena rasa hormat dan takut akan berbagai bahaya yang tersembunyi di dalam pegunungan.",
  str_aircraft_tactic_info23101 = "Bahan Perumahan Northland: Bahan bangunan yang digunakan di Northland adalah bahan-bahan dasar yang terbuat dari mineral mentah dan kayu yang diproses secara kasar. Namun, bukan berarti rumah-rumah di Northland tidak memiliki nilai estetika—bahkan, gaya alami mereka dipandang sebagai contoh keindahan yang murni dan tak bercela.",
  str_aircraft_tactic_info23102 = "Arsitektur Northland: Bangunan Northland umumnya tinggi dan sempit dengan kolom menjulang serta ramping. Ketinggian dan rentang puncaknya tidak terbatas serta bisa dibangun sebesar dan setinggi yang diinginkan.",
  str_aircraft_tactic_info23103 = "Konstruksi Perumahan Northland: Pembangun biasanya menggunakan kereta untuk mengangkut kayu guna tujuan konstruksi, terkadang dibantu oleh Luminatics. Misalnya, mereka mungkin menggunakan es untuk membentuk bingkai atau Lumina untuk memotong batu.",
  str_aircraft_tactic_info23104 = "Topografi Northland: Northland dikelilingi oleh hutan yang berfungsi sebagai penghalang alami dan akar sumber daya alam yang tak ada habisnya.",
  str_aircraft_tactic_info24101 = "Sawdust Bun: Ransum makanan yang dibuat ketika perang berkobar dan telah diberikan kepada para prajurit hingga saat ini. Meskipun rasanya agak ganjil, anehnya roti ini mengenyangkan dan memberikan nutrisi yang cukup untuk prajurit biasa. Karena diduga dicampur dengan berbagai bahan kotor yang bisa dimakan dan mirip dengan serbuk gergaji, Illumina Federation sering menyebut ransum ini sebagai \"Sawdust Bun\".",
  str_aircraft_tactic_info24102 = "Cokelat: Penduduk wilayah yang lebih dingin tentunya lebih terbiasa dengan hidangan penutup yang diawetkan. Maka dari itu, cokelat, dengan cita rasa lembut dan manis, telah menjadi salah satu dari sedikit produk impor yang populer di Northland.",
  str_aircraft_tactic_info24103 = "Ternak Northland: Orang-orang Northland memelihara hewan jinak, seperti rusa, domba, dan unggas. Namun, mereka juga sering menyantap binatang buas, seperti beruang cokelat dan babi hutan, yang hanya bisa ditaklukkan oleh pemburu.",
  str_aircraft_tactic_info24104 = "Memancing: Daerah pesisir Northland sangat ideal untuk memancing, begitu pula daerah pedalaman di sepanjang sungai dan danaunya. Namun, Aurorian di Northland tidak berburu di Lake Mirror. Menurut legenda dan tradisi berabad-abad, tempat itu dianggap sebagai wilayah suci.",
  str_aircraft_tactic_info25101 = "Garam: Garam dasar yang bisa dimakan ini disuling dari laut Northland oleh penduduk desa di wilayah tersebut. Kelebihan garam ditukar dengan barang lain-lain melalui perdagangan. Secara umum, penduduk setempat menggunakan lebih sedikit garam daripada di wilayah lain karena mereka lebih dekat dengan laut dan bisa menambah asupan garam mereka menggunakan ikan laut.",
  str_aircraft_tactic_info25102 = "Distribusi Garam: Penjualan garam relatif minim di Northland. Meskipun para penduduk yang tinggal di tepi pantai bisa mendapatkan garam dengan sangat mudah, mereka tidak terlalu suka menggunakannya dalam masakan karena bahan-bahan yang diperoleh dari laut sudah cukup gurih. Permintaan garam dari wilayah pedalaman lebih tinggi, tetapi saluran pasokan di Northland relatif terbelakang. Ini berarti bahwa orang sering kali harus pergi ke tepi laut untuk membeli garam.",
  str_aircraft_tactic_info25103 = "Danau Air Asin: Ada beberapa danau air asin besar di Northland. Temuan para ahli menyatakan bahwa danau tersebut, sebenarnya, adalah lautan yang ditinggalkan yang berubah bentuknya akibat perubahan struktur benua kuno.",
  str_aircraft_tactic_info25104 = "Serigala Salju: Pemangsa ganas dari Northland ini hidup berkelompok dan sepertinya memiliki kebijaksanaan yang melampaui binatang buas biasa.",
  str_aircraft_tactic_info26101 = "Pine Frost Valley: Salah satu wilayah yang mengarah keluar dari Northland. Sebuah pos jaga dibangun di sini sebagai pertahanan dari penyerbuan Eclipsite.",
  str_aircraft_tactic_info26102 = "Wonder Village: Desa di perbatasan Northland ini memiliki populasi yang relatif besar dan ukurannya kini setara dengan kota kecil.",
  str_aircraft_tactic_info26103 = "Northland Pine: Bukit ini menyimpan banyak kristal yang belum dimanfaatkan. Penduduk desa yang terbagi menjadi beberapa kepemilikan lahan, besar dan kecil, tersebar di tanah datar antara perbukitan.",
  str_aircraft_tactic_info26104 = "Windward Forest: Hutan yang terletak di selatan Northland ini menawarkan iklim yang hangat sepanjang tahun dan merupakan habitat bagi banyak flora dan fauna.",
  str_aircraft_tactic_info27101 = "Luminatics di Northland: Aurorian di Northland mendukung pentingnya alam dalam segala hal dengan memahami proses Lumina paling mendasar yang difasilitasi oleh alam, beresonansi dengan entitas alam, dan turut campur tangan pada dunia melalui alam imajinasi dan persepsi mental.",
  str_aircraft_tactic_info27102 = "Media Luminatics di Northland: Luminatics sering kali membutuhkan media alami yang murni untuk Aurorian di Northland. Media yang paling umum adalah alat yang terbuat dari cabang pohon dan beberapa Aurorian bisa menjadikan hewan sebagai perantaranya. Dibandingkan dengan upacara Lumopolis, Luminatics di Northland lebih primitif sehingga bisa menciptakan efek yang lebih mendasar, tetapi efeknya sering kali lebih kuat.",
  str_aircraft_tactic_info27103 = "Kepercayaan di Northland: Orang Northland percaya bahwa segala sesuatu memiliki jiwa dan bahwa segala sesuatu bisa diajak berkomunikasi—baik itu hewan, tumbuhan, lingkungan, maupun fenomena.",
  str_aircraft_tactic_info27104 = "Kepercayaan dan Kepemimpinan: Kepercayaan di Northland tidak mengikuti struktur organisasi yang ketat, dan dengan demikian, tidak berdampak pada aturan keluarga kerajaan. Sebenarnya, pemerintahan keluarga kerajaan Northland selalu relatif terlepas dari agama sehingga membentuk struktur unik yang hampir sejajar dengan sistem kepercayaan populer.",
  str_aircraft_tactic_info28101 = "Luminatics di Illumina: Luminatics yang digunakan oleh Illumina Federation berbeda dengan yang digunakan di tempat lain dan lebih fokus pada teknik—dengan menggunakan media mekanis yang dikembangkan melalui teknologi, para penggunanya bisa merapalkan mantra tanpa harus mengasah pikiran mereka.",
  str_aircraft_tactic_info28102 = "Anjing Kereta Luncur: Penduduk Northland sering memelihara anjing jenis ini. Mereka mahir menarik kereta luncur dan menemani pemiliknya saat berburu. Mereka bahkan merupakan jenis hewan peliharaan yang populer.",
  str_aircraft_tactic_info28103 = "Kehidupan Sehari-Hari di Northland: Kehidupan sehari-hari orang Northland hampir sama. Pekerjaan dimulai saat matahari terbit dan berakhir saat matahari terbenam, dan setiap orang memiliki tugas masing-masing untuk dikerjakan, baik itu bertani, beternak, berburu, maupun kerja kasar. Orang tua sering merawat anak-anaknya di rumah dan mengajarkan semua pengetahuan yang mereka miliki.",
  str_aircraft_tactic_info28104 = "Transportasi Manual: Transportasi manual adalah jenis yang paling umum di Northland. Untungnya, banyak Aurorian bisa menggunakan Luminatics untuk membantu mereka dalam hal ini.",
  str_aircraft_tactic_info29101 = "Pertemuan Festival: Penduduk Northland hidup sederhana dan tidak memiliki keinginan yang aneh-aneh. Hampir setiap hari, mereka jarang mencari hiburan atau terlibat dalam kegiatan sosial. Semua orang berkumpul dan berbagi segala hal menarik yang mereka lakukan baru-baru ini hanya selama festival.",
  str_aircraft_tactic_info29102 = "Kegiatan Sosial: Selama festival, seperti Tahun Baru, orang suka duduk-duduk dan mengobrol, menyanyi, mengikuti lomba mendongeng, atau pergi piknik di hutan terdekat. Para laki-laki sering mengadakan pesta berburu.",
  str_aircraft_tactic_info29103 = "Makanan Khas: Sebagian besar makanan khas Northland terdiri dari hidangan penutup, biasanya disajikan oleh keluarga kerajaan saat menjamu tamu. Selain itu, akan ada berbagai makanan laut di atas meja, seperti anjing laut panggang dan daging hiu yang difermentasi.",
  str_aircraft_tactic_info29104 = "Alkohol: Minuman beralkohol setempat mencakup anggur madu dan gin dan nama-nama minuman ini sering menggabungkan unsur es dan salju.",
  str_aircraft_tactic_info30101 = "Perbatasan Tertutup: Meskipun baru-baru ini terlibat dalam perdagangan dengan negara-kota lain, Northland tetap relatif tertutup. Banyak orang yang tinggal di desa dan kota pedalaman Northland jarang mendapatkan kesempatan untuk bertemu orang luar, jadi mereka menyambut pengunjung dengan sepenuh hati dan sangat ingin mendengar berita tentang dunia luar. Karena itu, orang-orang menganggap penduduk asli Northland bersifat hangat dan ramah.",
  str_aircraft_tactic_info30102 = "Sifat Penduduk Northland: Karena bertahun-tahun hidup terisolasi dan mandiri, para penduduk Northland memiliki karakteristik yang sederhana dan berhati bersih, tetapi mereka juga bisa keras kepala dan tak mau menerima perubahan. Misalnya, ketakutan akan ide-ide baru ini membuat mereka sulit beradaptasi dengan gaya hidup yang serba cepat dan berorientasi komersial di tempat seperti Umbraton.",
  str_aircraft_tactic_info30103 = "Kesadaran akan Magis: Para penduduk Northland tidak mudah terkejut dengan hal-hal dan peristiwa yang bertentangan dengan akal sehat dan bahkan terbiasa dengan fenomena seperti itu. Misalnya, ketika bertemu dengan rusa yang bisa berbicara, orang Northland akan berbicara dengannya secara normal tanpa mempertanyakan kejadian aneh tersebut.",
  str_aircraft_tactic_info30104 = "Perdagangan di Northland: Karena Northland berbatasan dengan laut, kapal-kapal berlabuh di pelabuhannya secara teratur untuk membawa barang-barang impor yang eksotis. Namun, penduduk Northland tidak tertarik dengan barang-barang mewah sehingga para pedagang sering kali buru-buru ingin meninggalkan Northland untuk mengunjungi negara-kota Astra lainnya.",
  str_aircraft_tactic_info31101 = "Regu Pencari: Desa-desa di Northland membentuk regu pencari saat dibutuhkan—untuk melacak Eclipsite yang menyerang, mencari Aurorian yang hilang, dan hal-hal penting lainnya. Jumlah anggota regu pencari ini tidak tetap dan mereka biasanya terdiri dari empat hingga enam anggota. Cakupan dari regu-regu ini umumnya berpusat di sekitar desa meskipun mereka mungkin juga fokus pada area di tempat Eclipsite telah terlihat. Para Elder meminta semua pria dewasa untuk membantu sementara pemburu atau penduduk yang akrab dengan hutan belantara ditugaskan untuk memimpin.",
  str_aircraft_tactic_info31102 = "Pendidikan Northland: Northland tidak memiliki sistem pendidikan standarnya sendiri dan pada dasarnya semua pengetahuan disampaikan secara lisan.",
  str_aircraft_tactic_info31103 = "Hukum Northland: Tidak ada hukum tertulis di Northland dan keadilan biasanya bergantung pada moralitas spontan penduduk desa ketika berinteraksi satu sama lain. Penguasa setempat atau lembaga yang berkuasa juga bisa dipanggil untuk menengahi perselisihan.",
  str_aircraft_tactic_info31104 = "Kepemimpinan Northland: Penduduk Northland tidak menyukai campur tangan orang luar dalam pengelolaan permukiman mereka. Karena setiap desa dan kota memiliki keunikan dan sejarahnya sendiri yang berusia hingga ribuan tahun, mereka percaya bahwa praktik saat ini sudah memadai.",
  str_aircraft_tactic_info32101 = "Legenda dari Northland: Konon, Aurorian asli berasal dari Northland dan mereka memperoleh kekuatan besar dengan bermandikan cahaya Aurora. Para Aurorian di Northland memiliki hubungan yang mendalam dengan negeri mereka dan, terlepas dari perubahan besar di dunia luar, mereka akan selalu menganggap rumah mereka sebagai tanah suci pertama dan terakhir.",
  str_aircraft_tactic_info32102 = "Northland Saat Ini: Karena perbatasannya secara bertahap mulai terbuka, Northland makin dikenal oleh banyak orang luar. Para penduduk Rediesel Desert pun bahkan telah mendengar desas-desus tentang tempat ini. Negara-kota lain di benua itu terkadang menerima penduduk asli Northland yang bepergian ke luar negeri dan menyambut setiap kesempatan untuk membeli segala macam barang yang berasal dari Northland. Namun, Northland dipandang sebagai negeri yang tidak terkenal akibat terisolasi untuk waktu yang lama dan, terutama di mata orang biasa, Northland tetap menjadi tempat misterius yang berkaitan dengan semua jenis sihir dan hal-hal rahasia.",
  str_aircraft_tactic_info32103 = "Penguasa Northland: Saat ini, Bethlehem adalah satu-satunya anggota keluarga kerajaan Northland. Dia telah menjadi satu-satunya penguasa yang memikat hati penduduk Northland dengan Luminatics yang kuat dan darah bangsawannya. Semua orang Northland sangat menghormati Bethlehem dan tak ada yang berani melawan perintahnya atau mempertanyakan keputusannya.",
  str_aircraft_tactic_info32104 = "Keluarga Kerajaan Northland: Keluarga kerajaan Northland adalah penguasa tersumpah dan pelindung Northland. Keluarga kerajaan memiliki kekuatan tak tertandingi yang diturunkan dari generasi ke generasi serta telah memerintah selama ribuan tahun.",
  str_aircraft_tactic_info33101 = "Buku di Northland: Buku adalah barang langka di Northland dan pengetahuan diturunkan secara lisan selain melalui ukiran, ikatan simpul tali, dan tablet kayu. Kalaupun ada, buku terbuat dari perkamen.",
  str_aircraft_tactic_info33102 = "Furnitur: Northland memiliki gaya dekorasi interiornya sendiri yang mengedepankan kesederhanaan alih-alih kemewahan. Meskipun sederhana, gaya ini tetap terlihat anggun dan estetis berkat penataan dan penempatan objek.",
  str_aircraft_tactic_info33103 = "Musik: Karena musik di Northland terutama dinikmati oleh anak-anak, gaya musik wilayah ini ringan dan cepat sehingga sangat cocok untuk mengiringi dongeng.",
  str_aircraft_tactic_info33104 = "Militer Northland: Northland tidak memiliki tentara permanen. Karena wilayah terpencil ini tidak melibatkan diri dalam urusan negara-kota Astra, setiap permukiman memiliki milisi pertahanan yang dibentuk sendiri-sendiri dan biasanya tidak beranggotakan lebih dari seribu tentara.",
  str_aircraft_tactic_info40101 = "Korespondensi antara Umbraton dan Rediesel Desert: Secara umum, sebagian besar korespondensi disampaikan oleh orang-orang yang dikenal dan dipercaya. Waktu pengiriman bisa sangat bervariasi, tetapi satu perjalanan antara dua lokasi memakan waktu sekitar satu bulan. Namun, waktu pengiriman bisa dipersingkat menjadi hanya satu minggu jika menggunakan layanan profesional Courier Union.",
  str_aircraft_tactic_info40102 = "Rediesel Wrench: Sekelompok pengembara dan penjahat nomaden yang menghuni Rediesel Desert. Awalnya, mereka merupakan bagian dari Advance Team Illumina yang ditugaskan untuk menjelajahi permukaan dan Undercity. Namun, setelah kekalahan tragis di Secret Territory, mereka pun meninggalkan Illumina Federation dan berlindung di Rediesel Desert. Seiring waktu, perlahan mereka menjadi bandit nomaden seperti yang dikenal sekarang.",
  str_aircraft_tactic_info40103 = "Kebudayaan Rediesel Wrench: Ciri utama kebudayaan Rediesel Wrench adalah kebebasan yang berdampingan dengan anarki total. Kelangsungan hidup adalah tujuan utama; hal-hal lain hanya pemanis dalam hidup mereka.",
  str_aircraft_tactic_info40104 = "Tata Tertib di Rediesel Wrench: Tidak ada.",
  str_aircraft_tactic_info40201 = "Hovercraft: Moda transportasi utama yang digunakan oleh Advance Team Illumina selama penjelajahan mereka. Meskipun kurang nyaman, kendaraan yang sangat berguna ini mampu melintasi berbagai medan yang sulit. Karena Illumina sangat mementingkan penjelajahan dan penelitian, Federation menggunakan Hovercraft untuk membawa Advance Team yang mereka utus ke area di luar jangkauan orang biasa.",
  str_aircraft_tactic_info40202 = "Struktur Hovercraft: Hovercraft dibuat berdasarkan pada desain truk biasa. Kendaraan ini juga dilengkapi dengan bantalan udara yang tahan lama sehingga bisa melayang dan melintasi berbagai jenis medan yang lebih luas (bukit pasir, rawa, dll…).",
  str_aircraft_tactic_info40203 = "Pengoperasian Hovercraft: Dalam keadaan normal, aturan pengoperasian Hovercraft tidak berbeda dengan truk biasa. Untuk melayang, Hovercraft harus berada dalam jarak setengah meter dari tanah. Selain itu, karena Hovercraft kurang stabil saat melayang, pengangkutan instrumen presisi besar juga dilarang.",
  str_aircraft_tactic_info40204 = "Sistem Lokomotif Hovercraft: Guna mempertahankan kemampuan mengambangnya, Hovercraft menggunakan ventilator khusus untuk mengganti udara dalam bantalannya secara berkala. Dalam perjalanan melintasi bioma gurun, kipas khusus harus dipasang untuk mengeluarkan pasir dan partikel lainnya.",
  str_aircraft_tactic_info40301 = "Badai Pasir: Badai pasir adalah peristiwa alami yang umum di Rediesel Desert dan biasanya terjadi setiap 24 hingga 48 jam. Para penduduk gurun terbiasa menunggu badai di lubang pasir atau tempat perlindungan sementara lainnya. Umumnya, kehidupan sehari-hari mereka tidak terganggu oleh angin dan pasir yang menderu.",
  str_aircraft_tactic_info40302 = "Perbedaan Suhu: Sebagian besar Rediesel Desert bersuhu lebih dari 50°C di siang hari dan suhu turun menjadi sekitar 5°C di malam hari. Di bagian utara gurun yang sedikit lebih dingin, suhu di siang hari bisa mencapai kira-kira 40°C, tetapi akan turun di bawah 0°C di malam hari.",
  str_aircraft_tactic_info40303 = "Permukiman Gurun Aurorian: Sebagian besar Aurorian yang menghuni Rediesel Desert tinggal di kota Oasis, sedangkan beberapa memilih untuk tinggal di perbatasan gurun. Meskipun penghuni gurun nomaden ini melakukan perjalanan melintasi pasir sepanjang tahun, pilihan mereka masih terbatas akibat kelangkaan air.",
  str_aircraft_tactic_info40304 = "Tindakan Perlindungan: Setiap rumah tangga memiliki \"sarang pasir\" bawah tanahnya sendiri untuk berlindung dari badai pasir. Perabotan, peralatan, dan barang-barang lainnya biasanya dibungkus dengan kantong plastik atau kain untuk melindunginya dari sinar matahari dan pasir.",
  str_aircraft_tactic_info40401 = "Toko Barang Bekas: Toko penuh kejutan dan keajaiban yang menghiasi lanskap gurun. Orang tidak pernah tahu apa yang menanti mereka di dalam: mungkin harapan terbesar, atau mungkin kejutan yang tak terduga?",
  str_aircraft_tactic_info40402 = "Barang dari Gurun: Sampah seseorang adalah harta bagi orang lain dan bukan hal aneh jika kita bisa menemukan \"harta karun\" ini di toko barang bekas. Segala macam barang berharga bisa ditemukan di tempat barang rongsokan atau justru berserakan di gurun. Terkadang, nilai dari harta karun semacam ini hanya bisa diketahui jika ada yang mau membelinya.",
  str_aircraft_tactic_info40403 = "Barang Sisa nan Murah: Anggota Rediesel Wrench sering menemukan barang-barang aneh dan tidak biasa. Mereka cenderung menjual barang-barang tersebut ke toko barang bekas jika tidak ada gunanya. Tentu saja, toko-toko ini juga berfungsi sebagai pegadaian bagi penghuni gurun lainnya.",
  str_aircraft_tactic_info40404 = "Lakukan Sendiri: Toko barang bekas dikenal akan kemampuannya merekonstruksi atau bahkan memodifikasi barang temuan dengan potongan-potongan yang berserakan di sekitar bengkel mereka. Meskipun tentu saja gagal memenuhi standar pabrikan aslinya, barang-barang ini tetap berguna di tempat yang tidak bersahabat dan tidak terduga seperti Rediesel Desert.",
  str_aircraft_tactic_info40501 = "Pembentukan Geng Gurun: Penduduk nomaden Rediesel Desert membentuk sejumlah besar geng bandit. Selain terbiasa menghabiskan hari-hari mereka untuk menjelajahi gurun demi mencari barang-barang berharga, mereka juga diketahui menyergap para pelancong dan bahkan bersatu padu untuk menyerang karavan militer Illumina.",
  str_aircraft_tactic_info40502 = "Gaya Kebanditan: Geng gurun biasanya memangsa yang lemah sambil menghindari yang kuat. Mereka tidak memiliki pedoman atau keraguan, apalagi moral, dan tanpa malu-malu berpikir serta bertindak dengan egois.",
  str_aircraft_tactic_info40503 = "Bandit dan Rediesel Wrench: Rediesel Wrench ditakuti oleh mayoritas geng dan bandit gurun karena kelompok itulah yang menghukum geng-geng dan para bandit tersebut atas kebanditan mereka. Sering kali, mereka akan langsung berbalik dan berlindung dalam pasir jika melihat Rediesel Wrench.",
  str_aircraft_tactic_info40504 = "Fragmen Teknologi: Kepingan teknologi ini sering digali di seluruh Rediesel Desert. Meskipun tak ada yang yakin tentang asal-usul atau fungsinya, ada satu hal yang semua orang yakini: harganya selalu mahal di pasaran.",
  str_aircraft_tactic_info40601 = "Hari Lumopolis: Hari Lumopolis adalah hari libur untuk merayakan berdirinya kota Lumopolis. Perayaan tersebut menunjukkan kekuatan Lumopolis kepada dunia dan menanamkan rasa hormat pada penduduknya. Hanya hiasan paling mewah yang digunakan untuk perayaan itu, sebuah penghargaan yang mencolok untuk kekayaan kota yang sangat besar. Pejabat asing dan tamu penting lainnya sering diundang untuk ikut serta dalam perayaan, yang berujung pada pesta mewah.",
  str_aircraft_tactic_info40602 = "Camilan Hari Lumopolis: Selama perayaan, jalan-jalan di Lumopolis dipenuhi dengan kios camilan yang menawarkan semua barang dagangan mereka secara cuma-cuma. Penduduk Lumopolis akan menghidangkan pai buah buatan sendiri dan suguhan lezat lainnya untuk perayaan besar itu.",
  str_aircraft_tactic_info40603 = "Hari Lumopolis - Peraturan Masuk/Keluar: Selama perayaan, peraturan masuk dan keluar dilonggarkan agar ada lebih banyak orang asing yang ikut serta. Pada Hari Lumopolis, pengunjung tidak perlu mencemaskan biaya selama liburan ini karena sebagian besar barang dan jasa ditawarkan secara gratis.",
  str_aircraft_tactic_info40604 = "Pesta Sunyi: Ada lelang sangat unik yang diadakan di Umbraton. Dari luar, acara itu tampak tidak ada bedanya dengan perjamuan lainnya. Para tamu menikmati hidangan-hidangan terlezat dan hiburan yang ditawarkan kota ini. Namun, selama pesta spesial ini, segala jenis transaksi dengan harga yang mengejutkan dilakukan tanpa mengucapkan sepatah kata pun…",
  str_aircraft_tactic_info40701 = "Genre Musik: Wilayah yang berbeda menyukai gaya musik yang berbeda pula, tergantung pada selera individu dan kebudayaan mereka. Sementara Lumopolis menikmati musik yang elegan dan halus, Rediesel Desert berdenyut dengan musik yang penuh energi dan gairah. Musik di Northland sederhana tetapi meriah, sedangkan musik di Illumina Federation lebih muram dan tenang…",
  str_aircraft_tactic_info40702 = "Alat Musik: Alat musik tidak bisa dipisahkan dengan gaya musik yang disukai suatu wilayah. Biola, piano, dan organ mendominasi musik Lumopolis, sementara gitar listrik, gitar bass, dan drum adalah pemandangan umum dan disambut baik di pub-pub Rediesel Desert. Alat musik tiup kayu sudah menjadi bagian dari barang rumah tangga penduduk Northland, sedangkan alat musik tiup logam lebih disukai di Illumina Federation.",
  str_aircraft_tactic_info40703 = "Musisi: Lumopolis memiliki jumlah musisi terkenal paling banyak, kemungkinan karena banyak orang beranggapan bahwa biola dan piano merupakan alat musik yang paling elegan. Namun, penduduk yang lebih muda lebih tertarik pada gitar dan drum daripada pilihan yang lebih \"halus\".",
  str_aircraft_tactic_info40704 = "Pendidikan Musik: Meskipun ada banyak sekolah yang menawarkan kurikulum mengenai musik sampai tingkat tertentu, tidak ada akademi musik profesional untuk calon musisi. Akibatnya, akan lebih baik bagi orang-orang yang ingin berkarier di bidang musik untuk mencari bimbingan dari para seniman yang sudah mapan dan sukses.",
  str_aircraft_tactic_info40801 = "Konvoi Illumina: Setiap konvoi Illumina terdiri dari dua hingga empat truk kargo, masing-masing membutuhkan dua pengemudi. Selain itu, minimum tiga sepeda motor sespan ditugaskan sebagai pengawal keamanan untuk setiap truk.",
  str_aircraft_tactic_info40802 = "Rute Transportasi Konvoi: Konvoi umumnya bertanggung jawab atas pengangkutan barang antara berbagai Undercity. Karena keterbatasan fisik truk konvoi, jalan yang relatif lebar dipilih sebagai jalur transportasi. Pengangkutan barang di luar jalur perdagangan yang telah ditetapkan ini hanya dilakukan oleh sejumlah kecil konvoi.",
  str_aircraft_tactic_info40803 = "Sarana Transportasi: Truk Gaz adalah kendaraan pilihan Illumina Federation untuk transportasi industri. Truk raksasa yang bertenaga besar, efisien, dan mudah diproduksi massal ini dianggap agak \"jelek\" secara estetika, tetapi kegunaan dan kepraktisannya tidak bisa disangkal.",
  str_aircraft_tactic_info40804 = "Barang yang Diangkut: Konvoi Illumina Federation umumnya mengangkut bijih yang ditambang, komponen yang diproduksi di Gannon, dan kebutuhan sehari-hari. Selain itu, konvoi sering ditugaskan untuk mengangkut senjata militer meskipun spesifikasinya dirahasiakan dari orang luar.",
  str_aircraft_tactic_info40901 = "Pernikahan di Umbraton: Tidak ada aturan atau sertifikasi apa pun yang diperlukan untuk pernikahan di Umbraton. Untuk para anggota dari sindikat kejahatan yang berbeda, persetujuan bos umumnya diperlukan; bagi warga biasa, persetujuan orang tua dari kedua belah pihak sudah lebih dari cukup.",
  str_aircraft_tactic_info40902 = "Upacara Pernikahan di Umbraton: Pernikahan sering kali merupakan acara yang megah di Umbraton. Orang tua pengantin baru memberikan hadiah-hadiah mahal untuk menghormati mereka sekaligus sebagai simbol restu atas pernikahan mereka.",
  str_aircraft_tactic_info40903 = "Gerbang Bunga: Gerbang-gerbang dihias cantik dengan bunga untuk pernikahan Umbraton. Melintasi gerbang bunga ini secara bersama-sama melambangkan awal dari persatuan abadi pasangan. Sampai batas tertentu, keindahan dan detail gerbang ini menunjukkan kebahagiaan masa depan pengantin baru. Tentu saja, sangat penting untuk memilih bunga yang menyiratkan makna yang tepat.",
  str_aircraft_tactic_info40904 = "Kriteria Seleksi: Kriteria yang paling umum (dan sering kali paling penting) saat mencari pasangan di Umbraton adalah stabilitas keuangan, pilihan mendasar dalam masyarakat hiperkomersial. Ketika menanyakan mana yang lebih penting, uang atau cinta, ada baiknya untuk diingat bahwa di Umbraton, uang bahkan bisa membeli cinta terindah. Namun, di sisi lain, cinta tidak serta-merta bisa memenuhi kebutuhan hidup.",
  str_aircraft_tactic_info41001 = "Rediesel: Material berwarna merah tua yang biasa digunakan dalam cat. Material ini semula dibuat di Rediesel Desert, tempat banyak hal juga dicat merah (umumnya karena kurangnya warna lain).",
  str_aircraft_tactic_info41002 = "Sandworm: Makanan yang umum di gurun. Saat digoreng, rasa dan teksturnya cukup enak, dan mudah disimpan untuk konsumsi di masa depan. Jangan pernah meremehkan nilai dari makhluk ini karena mereka kaya akan nutrisi dan bahkan bisa terasa seperti ayam jika diolah dengan benar!",
  str_aircraft_tactic_info41003 = "Kadal: Makanan umum di gurun. Umumnya dikeringkan sebelum dimasak, dagingnya kenyal dan gurih, dan kulitnya biasanya disamak untuk dijadikan barang-barang dari kulit. Karena kualitasnya, barang-barang dari kulit kadal banyak diburu oleh sejumlah orang luar.",
  str_aircraft_tactic_info41004 = "Kaktus: Tanaman gurun yang jarang terlihat dan sering digunakan untuk membuat minuman khusus. Meskipun kadar airnya sangat rendah, konon aromanya yang kaya mampu memikat para karnivora yang menghuni gurun. Bahkan konon minuman yang terbuat dari kaktus berkhasiat untuk memperkuat tubuh dan mempercantik kulit.",
  str_aircraft_tactic_info41101 = "Komunikasi di Rediesel Desert (1): Tidak ada sistem telekomunikasi tetap di Rediesel Desert, dan sebagian besar informasi disampaikan dari mulut ke mulut. Akibatnya, informasi yang diterima penduduk gurun sering tertinggal jauh di belakang bagian dunia lainnya; dalam beberapa kasus, ada orang yang bahkan belum pernah mendengar tentang Lumopolis!",
  str_aircraft_tactic_info41102 = "Komunikasi di Rediesel Desert (2): Setelah pengenalan produk teknologi dasar dari Illumina Federation, permukiman gurun yang lebih besar mulai menggunakan radio dan protofon untuk berkomunikasi. Meskipun saluran yang berbeda untuk komunikasi sudah dibuat, saluran-saluran itu justru berulang kali digunakan secara bergantian dan akibatnya sering mengalami gangguan.",
  str_aircraft_tactic_info41103 = "Eclipsite di Rediesel Wrench: Sejumlah besar Eclipsite berkeliaran di bagian utara dan barat gurun, sedangkan pertempuran di bagian selatan dan timur hanya sedikit dan jarang terjadi. Terlepas dari lokasinya, dengan mengandalkan pengalaman dan kewaspadaan, penghuni Rediesel Desert sebisa mungkin menghindari konfrontasi dengan Eclipsite.",
  str_aircraft_tactic_info41104 = "Pertahanan Eclipsite: Struktur pertahanan dasar, seperti dinding besi tua dan benteng, sering kali dibangun di permukiman gurun yang lebih besar untuk melindungi diri dari ancaman Eclipsite. Di sisi lain, permukiman yang lebih kecil dan pengembara yang menyendiri tidak punya banyak pilihan selain melarikan diri.",
  str_aircraft_tactic_info41201 = "Umbraton: Umbraton adalah percampuran kota-kota yang terletak tepat di bawah pulau terapung Azurite. Letaknya yang berada di dataran tengah Astra membuat lokasinya sempurna untuk transportasi darat serta untuk mengakses pusat perdagangan paling makmur di benua itu: Lumopolis.",
  str_aircraft_tactic_info41202 = "Asal-usul Umbraton: Awalnya, Umbraton dijadikan sebagai sektor kumuh Lumopolis dan berada di bawah otoritas langsung sheriff. Namun, seiring bertambahnya ukuran dan populasi, pemerintahan atas Umbraton menjadi makin tidak stabil. Akhirnya, sektor itu menjadi wilayah yang berdiri sendiri. Sekarang, Umbraton dikendalikan sepenuhnya oleh guild pedagang setempat, serta berbagai geng dan sindikat yang bersaing.",
  str_aircraft_tactic_info41203 = "Arsitektur Umbraton: Meski sebagian besar Umbraton terdiri dari rumah-rumah yang jelek, padat, dan tidak teratur, bangunan-bangunan dekoratif yang didirikan dengan lebih baik bisa dijumpai di pusat kota. Banyak dari bangunan ini merupakan markas dari berbagai guild Umbraton dan tempat hiburan, seperti bar serta kasino.",
  str_aircraft_tactic_info41204 = "Penghinaan terhadap Militer: Sebelum Darkover Crisis, Umbraton tidak pernah menjadi target serangan Eclipsite. Akibatnya, kota ini sangat tidak mementingkan urusan militer. Lagi pula, dalam masyarakat hiperkomersial yang menganggap bahwa kekayaan menentukan segalanya, apa gunanya tentara yang kuat jika gagal menghasilkan uang?",
  str_aircraft_tactic_info41301 = "Struktur Organisasi Rediesel Wrench: Rediesel Wrench dibagi menjadi beberapa tim yang lebih kecil, yang masing-masing beroperasi dengan aturannya sendiri, dan para pemimpin masing-masing tim mengikuti serta mematuhi perintah pemimpin Rediesel Wrench. Kepemimpinan Rediesel Wrench ditentukan melalui upacara serah terima jabatan dan pemimpin berikutnya mewarisi \"The Wrench\", simbol otoritas dalam organisasi.",
  str_aircraft_tactic_info41302 = "Hiburan \"Bergaya Rediesel\": Para anggota Rediesel Wrench hidup untuk menjarah dan menjarah untuk hidup. Bagi mereka, tidak ada yang lebih mengasyikkan atau menyenangkan ketimbang melakukan perampokan berbahaya yang memacu adrenalin. Konon, dalam beberapa kasus, anggota geng tertentu benar-benar mengembalikan barang curian kepada pemiliknya yang sah. Mereka mengatakan bahwa mereka lebih menikmati sensasi penjarahan daripada barang jarahan itu sendiri.",
  str_aircraft_tactic_info41303 = "Kebudayaan Umbraton: Umbraton tetap bersikap bebas dan berpikiran terbuka terhadap orang-orang dari berbagai ras dan latar belakang. Siapa pun bisa mencapai kesuksesan di Umbraton asalkan mereka punya otak encer dan kemauan untuk berhasil. Akibatnya, banyak industri bermunculan di seluruh kota, menawarkan segala hal yang dibutuhkan seseorang dengan harga yang tepat.",
  str_aircraft_tactic_info41304 = "Hukum Umbraton: Umbraton hanya memiliki sedikit hukum tertulis karena sebagian besar ketertiban ditegakkan melalui kekuatan berbagai geng dan sindikatnya. Intinya, selama orang tidak melanggar beberapa prinsip yang ditetapkan oleh penguasa yang ada (atau ketahuan melakukannya), apa pun dianggap \"sportif\". Akibatnya, kebanyakan orang di Umbraton lebih suka menangani urusan mereka di malam hari.",
  str_aircraft_tactic_info50101 = "Asal Usul Arena Bawah Tanah: Arena Bawah Tanah di Umbraton dulunya dikenal sebagai Pit, yang merupakan bentuk hiburan populer di kalangan bangsawan Lumo. Perkelahian mendebarkan yang terjadi di sana juga menarik banyak penonton dari masyarakat umum, dan lambat laun berkembang menjadi cara untuk menyelesaikan perselisihan antara berbagai kekuatan di Umbraton.",
  str_aircraft_tactic_info50102 = "Aturan Arena Bawah Tanah: Perkelahian biasanya diadakan dari jam 8 malam sampai jam 6 pagi. Tim beranggotakan lima orang saling bertarung berpasangan. Tidak ada batasan, dan cara menentukan pemenangnya brutal dan lugas: jika salah satu tim menyerah atau tidak bisa bertarung, tim tersebut kalah.",
  str_aircraft_tactic_info50103 = "Hadiah Arena Bawah Tanah: Tidak ada juara utama dalam pertandingan ini, hanya gelar Juara Tengah Malam. Tim dengan poin terbanyak dan tanpa kekalahan pada malam tertentu akan mempertahankan sabuk juara hingga malam berikutnya. Secara alami, tim mana pun yang dapat mempertahankan gelar selama beberapa malam akan menjadi objek penghormatan, serta kecemburuan.",
  str_aircraft_tactic_info50104 = "Perubahan di Arena Bawah Tanah: Arena Bawah Tanah pada masa-masa awal kacau dan berbahaya, karena berbagai kekuatan sering menggunakannya sebagai cara untuk menyelesaikan perselisihan. Kapan Istvan menjadi Shadowlord, dia menciptakan tiga aturan berikut: 1. Dilarang membunuh lawan. 2. Tidak boleh ada yang mengirimkan lebih dari satu tim. 3. Jika ada yang ingin membantah hasil pertandingan, mereka harus mengajukan keberatannya saat ini dan bukan di lain waktu.",
  str_aircraft_tactic_info50201 = "Tata kelola Umbraton Lumopolis: Jika Lumopolis pernah mengelola Umbraton, itu adalah untuk memungut pajak. Para bangsawan tidak pernah peduli akan jadi apa Umbraton, hanya berapa banyak uang yang bisa mereka keluarkan darinya. Akibatnya, sheriff dan pemungut pajak yang ditugaskan ke Umbraton segera bersekongkol dengan geng dan serikat di sini, dan merosot menjadi budak uang Umbraton.",
  str_aircraft_tactic_info50202 = "Keamanan bisnis di Umbraton: Satu aturan di Umbraton adalah tidak ada aturan. Mungkin Anda bisa menyebut kebebasan ini. Oleh karena itu, untuk memastikan keamanan mereka, serikat besar sering kali membentuk angkatan bersenjata swasta. Serikat yang lebih kecil akan mengumpulkan sumber daya mereka dalam usaha patungan untuk merekrut tentara bayaran, dan pedagang individu biasanya membayar biaya perlindungan kepada geng atau salah satu serikat.",
  str_aircraft_tactic_info50203 = "Geng Umbraton: Bangsawan yang diasingkan dari Lumopolis cenderung melanjutkan kehidupan mereka di Umbraton di sekitar keluarga, sementara desertir Federasi Illumina mempertahankan struktur hierarkis yang biasa mereka lakukan. Geng-geng lokal yang berbeda, sementara itu, saling menyapa dengan bahasa gaul dan jalanan. Umbraton menyambut dan mengakomodasi semua orang.",
  str_aircraft_tactic_info50204 = "Industri gelap: Di berbagai gang di Umbraton, pembeli dapat menemukan apa pun yang mereka inginkan — senjata dari Illumina Federation, barang-barang rumah tangga dari bangsawan Lumo, dan bahkan Eclipsites... Jangan tanya dari mana asalnya.",
  str_aircraft_tactic_info50301 = "Industri senjata di Umbraton: Senapan, amunisi, dan pistol dinas perwira dari Illumina, baju besi dan perisai tentara dari Lumopolis, dan bahkan pedang panjang dengan lambang keluarga bangsawan semuanya dapat ditemukan di Umbraton... selama pembeli mampu membayar harganya.",
  str_aircraft_tactic_info50302 = "Bisnis legal: Jika Anda ingin membeli senjata di Umbraton, sebaiknya jangan terlalu banyak bertanya tentang dari mana asalnya. Setiap pengusaha Umbraton akan memberi tahu Anda bahwa barang mereka legal, tetapi pernyataan itu harus diterima dengan sebutir garam.",
  str_aircraft_tactic_info50303 = "Penjualan kembali senjata: Sebagai pusat distribusi utama untuk kelompok yang ingin menjual barang dagangan demi keuntungan, senjata di Umbraton dijual secara pribadi. Pembeli yang bersedia membayar harganya juga dapat mengeluarkan komisi rahasia, dan seseorang di Umbraton akan dapat memperoleh apa yang mereka cari.",
  str_aircraft_tactic_info50304 = "Ekonomi pertunjukan sampingan: Untuk menghindari komplikasi yang tidak perlu, tidak ada serikat atau individu yang mengaku sebagai pedagang senjata. Namun, pembeli dapat memperoleh senjata dari orang atau serikat mana pun jika mereka dapat menemukan tempat yang tepat untuk mengumumkan penawaran yang masuk akal. Inilah dualitas profesionalisme dan side gigs di Umbraton.",
  str_aircraft_tactic_info50401 = "Kutipan dari adat pernikahan Lumopolis: Secara umum, perkawinan di Lumopolis bersifat relatif feodal, terutama jika menyangkut perkawinan antar kelas. Pertama, bangsawan dan rakyat jelata tidak boleh menikah. Kedua, kedua belah pihak yang melangsungkan perkawinan harus mendapat persetujuan dari keluarga atau orang tuanya. Ketiga, mereka mempraktikkan monogami, dan pasangan harus tetap setia satu sama lain.",
  str_aircraft_tactic_info50402 = "Pernikahan di bawah Dewa Cahaya: Pernikahan harus dilakukan di kuil Dewa Cahaya, dengan seorang pendeta sebagai saksi. Jika persyaratan ini tidak dipenuhi, pernikahan tidak akan dilindungi dan diberkati. Perselingkuhan terhadap pasangan sangat dilarang, dan pelaku kejahatan ini diadili, dengan hukuman mulai dari pencabutan gelar kebangsawanan hingga kematian.",
  str_aircraft_tactic_info50403 = "Konsekuensi pelanggaran: Bangsawan yang menikahi rakyat jelata karena cinta diasingkan dan menjadi rakyat jelata. Jika mereka pendeta, mereka dikucilkan.",
  str_aircraft_tactic_info50404 = "Pernikahan di kuil: Mereka yang telah mengambil sumpah seumur hidup untuk melayani Dewa Cahaya, seperti para pendeta, akan kehilangan semua hubungan dengan kehidupan duniawi, sementara mereka yang melayani kuil, seperti para ksatria, tidak diwajibkan secara ketat oleh Dewa Cahaya.",
  str_aircraft_tactic_info50501 = "Proses mengunjungi Lumopolis: Kecuali beberapa orang luar biasa, hampir tidak mungkin orang biasa memasuki Lumopolis. Orang biasa dapat menemukan berbagai cara menuju Umbraton, yang tentu saja mahal dan membutuhkan banyak kesabaran karena harus menunggu lama untuk pemeriksaan di zona transit.",
  str_aircraft_tactic_info50502 = "Zona Transit: Awalnya depot transportasi ditempatkan antara Umbraton dan Lumopolis, secara bertahap dibentuk menjadi zona transit karena banyaknya karavan yang tinggal di sana. Di tempat ini, Lumopolis melakukan pemeriksaan pendahuluan terhadap karavan dan personel sebelum mereka memasuki kota.",
  str_aircraft_tactic_info50503 = "Pemeriksaan Lumopolis: Memasuki Lumopolis bukanlah tugas yang mudah, karena orang harus melalui pemeriksaan identitas yang panjang dan melelahkan sebelum diberikan akses. Tentu saja, jika seseorang memiliki surat pengantar dengan lambang keluarga aristokrat, waktu tunggu dapat dikurangi secara signifikan.",
  str_aircraft_tactic_info50504 = "Rumah Tanpa Gangguan: Kesan pertama orang-orang tentang perumahan yang saling berdempetan di zona transit adalah jumlahnya yang sangat banyak, kepadatannya tinggi, dan tidak teratur sehingga mirip dengan permukiman di Umbraton. Hal ini umumnya diakibatkan oleh dibangunnya perumahan tersebut di sekitar stasiun transportasi. Perumahan dengan kepadatan tinggi tidak hanya memfasilitasi akses yang lebih cepat ke stasiun transportasi, tetapi juga memberikan rasa aman terhadap gangguan dari hutan belantara sehingga penghuninya merasa terlindungi.",
  str_aircraft_tactic_info50601 = "Orang menunggu: Alasan orang memasuki Lumopolis sangat bervariasi dari mengunjungi keluarga dan teman hingga bisnis, pariwisata, atau sekadar melihat-lihat kuil agung Dewa Cahaya. Penantiannya panjang dan membosankan, dan deretan penginapan di zona transit melayani orang-orang ini.",
  str_aircraft_tactic_info50602 = "Pemilik penginapan di zona transit: Untuk menunjukkan betapa beradabnya mereka, beberapa penduduk Lumopolis Bawah mengumpulkan dana untuk mendirikan penginapan. Di sana, mereka bisa menyambut pengunjung sekaligus memamerkan kekuatan Lumopolis kepada mereka. Penginapan yang diwaralabakan oleh klan utama Lumopolis hanya menerima tamu yang diundang oleh keluarga. Penginapan lain didanai oleh kuil dan eksklusif untuk pengikut God of Light. Penginapan yang dibuka oleh guild besar di Umbraton melayani karavan, tetapi juga terbuka untuk orang biasa yang lewat. Lagipula, masyarakat Umbraton tidak akan pernah melepaskan kesempatan untuk menghasilkan uang.",
  str_aircraft_tactic_info50603 = "Layanan Penginapan di Zona Transit: Selain makanan dan akomodasi biasa, penginapan di zona transit memberikan berbagai informasi kepada para penyewa. Ini terutama mencakup perkenalan ke Lumopolis, termasuk keluarga bangsawan, selebritas, kepercayaan, dan sebagainya. Secara alami, tidak ada kekurangan orang-orang yang terhubung dengan baik yang dapat memberikan layanan pelumasan hubungan bagi mereka yang tidak tahan dengan proses pemeriksaan yang lama.",
  str_aircraft_tactic_info50604 = "Pemandangan dan Harga Rumah di Zona Transit: Sebagai dampak dari begitu padatnya perumahan, pendatang yang menginap di zona transit dihadapkan pada pemandangan yang terbatas. Akibatnya, penginapan di lokasi yang bagus, terdiri dari beberapa lantai, dan terletak di dataran tinggi mahal harganya. Toh, pemandangan yang bagus bisa membuat hidup lebih nyaman saat menunggu untuk memasuki Lumopolis.",
  str_aircraft_tactic_info50701 = "Bangsawan dan Lambang Keluarga: Di Lumopolis, lambang keluarga menunjukkan keluarga mana yang dimiliki seseorang dan status mereka di Lumopolis. Meskipun pola yang rumit terlihat seperti tulisan yang sulit dipahami oleh orang luar, semua orang di Lumopolis mengenalnya. Bagaimanapun, mereka adalah bagian penting dari kehidupan sehari-hari mereka.",
  str_aircraft_tactic_info50702 = "Lambang Kuil: Kepercayaan pada Dewa Cahaya tersebar luas di seluruh Lumopolis. Dengan izin dari kuil, orang percaya dapat memakai lambang Dewa Cahaya atau menyulamnya di pakaian mereka untuk menunjukkan pengabdian mereka kepada Dewa Cahaya.",
  str_aircraft_tactic_info50703 = "Pakaian Indah di Umbraton: Pakaian mereka yang bagus, nyaman, dan berhiaskan aksesoris itu terbuat dari sutra berharga dari Timur atau bahan berharga lainnya di benua ini. Emas gelap dan ungu adalah dua warna yang disukai penduduk Umbraton untuk mengungkapkan sisi lain dari sikap mereka terhadap kehidupan - sikap yang liar.",
  str_aircraft_tactic_info50704 = "Busana Santai Umbraton: Sepatu bot dan mantel kulit, selendang dan turban yang menutupi seluruh wajah—inilah pakaian yang biasa dikenakan orang Umbraton. Ini berfungsi untuk menyembunyikan wajah mereka dengan lebih baik dan berbagai senjata yang mereka bawa.",
  str_aircraft_tactic_info50801 = "Hukum Lumopolis: Bangsawan dan rakyat jelata diatur oleh hukum yang berbeda. Status dan kekuatan yang sesuai dari keluarga seseorang memberikan hak yang berbeda, serta kekebalan tertentu.",
  str_aircraft_tactic_info50802 = "Persidangan di Lumopolis: Balai Kehakiman di Lumopolis umumnya bertanggung jawab atas ajudikasi, sementara Dewan Tetua menangani kasus yang melibatkan bangsawan. Dalam skenario terakhir, hakim akan ditunjuk oleh Penguasa Kota. Penunjukan Hakim Ketua membutuhkan persetujuan bulat dari Dewan Tetua dan kuil, yang biasanya merupakan hasil dari keseimbangan kekuatan di antara banyak pihak.",
  str_aircraft_tactic_info50803 = "Hukuman di Lumopolis: Orang biasa dan bangsawan yang melakukan kejahatan serius dianggap bertanggung jawab bersama dan biasanya dieksekusi dengan pedang atau digantung. Orang yang melakukan pelanggaran ringan dipenjara atau diasingkan.",
  str_aircraft_tactic_info50804 = "Tiang gantungan di Lumopolis: Saat eksekusi akan dilakukan, tiang gantungan sementara dipasang di alun-alun. Mereka biasanya menyertakan tiang tegak untuk mengikat narapidana, guillotine, dan bingkai kayu untuk digantung.",
  str_aircraft_tactic_info50901 = "Warisan di Umbraton: Meskipun orang-orang Umbraton sangat mementingkan kekayaan, mereka tidak dapat membawanya ketika mereka mencapai akhir hidup mereka. Seperti kodratnya, kebanyakan orang Umbraton mewariskan kekayaan dan statusnya kepada keturunan biologisnya.",
  str_aircraft_tactic_info50902 = "Pengaruh Surat Wasiat: Penduduk Umbraton yang menjalani kehidupan menyendiri atau karena berbagai alasan tidak memiliki kerabat biologis paling sering membuat surat wasiat di akhir hidup mereka. Seorang kenalan atau geng yang dapat diandalkan kemudian akan dipercaya untuk menangani properti mereka dan mengatur suksesi status mereka.",
  str_aircraft_tactic_info50903 = "Peran Orang Kedua: Untuk guild besar, pewaris darah dan surat wasiat terkadang mengalami kecelakaan, seperti kematian mendadak seorang ahli waris atau kematian kepala sekolah yang belum membuat surat wasiat. Dalam kebanyakan kasus seperti itu, orang kedua yang memegang komando mewarisi posisinya. Tentu saja, penunjukan orang kedua juga cenderung menimbulkan berbagai perselisihan.",
  str_aircraft_tactic_info50904 = "Keputusan Orang Banyak: Banyak suksesi menjadi kontroversial karena kekayaan dan status yang terlibat, yang telah menjadi penyebab banyak pertumpahan darah di Umbraton. Biasanya berakhir dengan satu pihak menang, atau lebih sering, dengan kedua belah pihak kalah, sehingga tidak ada yang mengambil alih. Pada titik ini, tokoh-tokoh terkemuka di Umbraton muncul untuk bersama-sama memutuskan bagaimana hal-hal harus ditangani. Setelah Shadowlord menguasai area tersebut, orang-orang menghormati keputusannya dalam masalah seperti itu.",
  str_aircraft_tactic_info51001 = "Bahan Bacaan: Di Umbraton, siapa pun yang mampu membelinya dapat dicetak tulisannya dengan mesin stensil. Dengan demikian, kota berkembang dengan segala jenis publikasi, termasuk majalah, majalah, surat kabar, dan selebaran.",
  str_aircraft_tactic_info51002 = "Naskah: Rakyat jelata di Lumopolis tidak diperbolehkan memiliki buku, termasuk salinan tulisan tangan. Hanya rumah bangsawan dan kuil yang menyimpan sejumlah besar manuskrip. Ini bukan hanya karena mereka diizinkan, tetapi terutama karena mereka mampu menyimpan banyak penyalin.",
  str_aircraft_tactic_info51003 = "Gulungan Perkamen: Wisatawan tidak perlu heran melihat orang-orang Northlander dengan tali yang diikat, tablet kayu bertulisan, atau bahkan tablet batu kecil dengan tulisan yang diukir di dalamnya. Ini adalah buku-buku mereka. Di Northland, di mana berita dari mulut ke mulut adalah sarana utama untuk menyampaikan pesan, bahan bacaan jarang ada, dan hanya peristiwa besar yang dicatat pada gulungan yang terbuat dari perkamen untuk diamankan.",
  str_aircraft_tactic_info51004 = "Buku Pribadi: Jika Anda melihat beberapa buklet atau gulungan tulisan tangan dengan teks yang tidak dapat dikenali, kemungkinan besar ini adalah karya beberapa organisasi yang ingin merahasiakan transaksi mereka dan menggunakan teks terenkripsi untuk dokumen mereka.",
  str_aircraft_tactic_info51101 = "Koran di Umbraton: Wartawan koran selalu terlihat sibuk. Bagaimanapun, surat kabar membutuhkan konten yang segar dan baru. Demi kecepatan, sebagian besar kantor berita besar memiliki mesin cetak dengan kualitas paling rendah yang dapat mencetak ribuan eksemplar surat kabar segera setelah isinya ditulis dan diketik. Surat kabar yang lebih kecil sering menyewa pengemudi khusus untuk mengirimkan manuskrip dengan cepat ke percetakan. Orang lain yang hanya memiliki sedikit orang yang bekerja untuk mereka menggunakan mesin cetak manual untuk stensil. Wajar jika surat kabar semacam itu diterbitkan dalam jumlah yang lebih sedikit, dan kualitasnya juga relatif buruk.",
  str_aircraft_tactic_info51102 = "Majalah Umbraton: Karena hanya percetakan yang memiliki pengikat dan pembuat sampul khusus, jika Anda ingin mencetak majalah, Anda harus mengirimkannya ke percetakan khusus. Namun, beberapa penerbit majalah juga menggunakan mesin cetak manual dan pengrajin non-profesional untuk mencetak dan menjilid majalah, sehingga kualitas majalah menjadi rendah. Konsekuensinya, mereka harus bergantung pada tajuk berita yang sangat baru dan sirkulasi cepat untuk mengamankan posisi mereka di pasar. Pada titik ini, majalah-majalah ini sebenarnya tidak jauh berbeda dengan surat kabar.",
  str_aircraft_tactic_info51103 = "Novel Umbraton: Kebebasan berbicara adalah etos terpenting dalam Umbraton. Siapa pun dapat menerbitkan karya mereka selama mereka mampu membayar biaya pencetakan dan distribusi. Wajar saja jika isinya terlalu ekstrim, percetakan dan penjual buku masih ragu apakah harus mengambil uangnya atau melanjutkan hidup.",
  str_aircraft_tactic_info51104 = "Buku Berbasis Pengetahuan di Umbraton: Hanya sedikit orang yang menunjukkan minat pada buku berbasis pengetahuan karena pragmatisme atau bahkan sekularisme yang berlaku di Umbraton. Semua orang di sana sibuk mencari uang. Orang yang berani menerbitkan buku semacam itu di Umbraton adalah sarjana kaya atau mendapat dukungan rahasia dari suatu organisasi.",
  str_aircraft_tactic_info51201 = "Berita di Lumopolis: Karena kelas bangsawan dan rakyat jelata berbeda, tidak ada publikasi berita publik di Lumopolis. Para bangsawan hanya peduli dengan apa yang terjadi di kalangan atas, di mana berita yang tidak akan pernah didengar oleh rakyat jelata disebarkan dari mulut ke mulut. Sementara itu, rakyat jelata hanya peduli dengan tindakan apa pun yang dilakukan para bangsawan atau kuil yang memengaruhi kehidupan mereka. Mereka biasanya diberitahu tentang hal-hal tersebut melalui pengumuman dari berbagai petugas administrasi di Lumopolis. Terkadang Lumopolis mendapatkan informasi tentang dunia luar saat seseorang membawa koran dari Umbraton.",
  str_aircraft_tactic_info51202 = "Koleksi Buku Lumopolis: Kuil Lumopolis memiliki koleksi buku terbesar. Personil khusus menyalin berbagai buku, mengkategorikannya, dan menyimpan catatan. Buku-buku itu disimpan di perpustakaan mereka, yang hanya dibuka untuk staf kuil. Para bangsawan juga menyimpan perpustakaan kecil di rumah mereka dan mengatur sejumlah klub dan salon buku yang agak eksklusif.",
  str_aircraft_tactic_info51203 = "Buku Kuil: Buku-buku yang mencakup berbagai risalah tentang agama Dewa Cahaya, keajaiban terkenal, dan pengalaman orang percaya merupakan sebagian besar koleksi di kuil Lumopolis. Secara alami, beberapa biksu yang berpikiran liberal menggunakan pemahaman mereka tentang Dewa Cahaya untuk menulis cerita sekuler yang menarik agar lebih banyak orang membaca dan memahami Dewa Cahaya.",
  str_aircraft_tactic_info51204 = "Dealer Buku di Lumopolis: Pada waktu-waktu tertentu, rakyat jelata dari Lumopolis muncul di Umbraton membawa setumpuk uang dan setumpuk manuskrip untuk dicetak dan diterbitkan. Disubsidi oleh bangsawan atau kuil, penjual buku ini sedikit anomali di Umbraton. Mereka tidak mencari keuntungan tetapi lebih mementingkan kualitas cetakan dan seberapa baik sirkulasi buku. Lagi pula, di mata rakyat jelata ini, lebih penting menyelesaikan tugas yang diberikan oleh atasan daripada mendapatkan uang.",
  str_aircraft_tactic_info51301 = "Pengadilan Rahasia Lumopolis: Di Taman Lumopolis, ada tempat penyimpanan file dan arsip rahasia. Dikatakan bahwa hanya Penguasa Kota Lumopolis, anggota penting dari Dewan Tetua, dan perwakilan dari keluarga bangsawan penting yang memiliki akses ke sana.",
  str_aircraft_tactic_info51302 = "The Jewel of Lumopolis: Daybreak Crystal adalah mineral langka yang dikatakan tidak ditemukan di pembuluh darah tetapi di lokasi yang tampaknya acak, yang membuatnya sulit untuk ditemukan dan ditambang. Bahkan bijih mentah memancarkan warna berbeda di bawah cahaya berbeda dan dari sudut berbeda, sementara batu yang dipoles memancarkan kaleidoskop warna yang sesungguhnya. Bahkan Bangsawan Lumo, yang telah melihat harta eksotis yang tak terhitung jumlahnya, tidak dapat menahan pesonanya.",
  str_aircraft_tactic_info51303 = "Lukisan Replika Umbraton: Ketika barang-barang mewah Lumopolis diperkenalkan ke Umbraton, mereka tidak hanya membawa kekayaan bagi penduduk setempat tetapi juga menginspirasi mereka untuk menghargai seni. Begitu orang-orang menjadi cukup kaya sehingga tidak perlu khawatir mencari nafkah, mereka mulai mengejar seni Lumopolis. Dan dengan demikian, lahirlah industri replikasi. Segala jenis lukisan cat minyak terkenal bisa ditemukan di Umbraton. Mereka ditampilkan di mana-mana, termasuk guild, kafe, dan bar. Bahkan dikabarkan bahwa upacara inisiasi beberapa geng melibatkan pembakaran lukisan.",
  str_aircraft_tactic_info51304 = "Kewaspadaan Umbraton: Sangat peka terhadap uang dan wilayah, pemilik usaha kecil di Umbraton cenderung sangat berhati-hati dengan ruang lingkup operasi mereka dan menghindari melewati batas yang tidak terucapkan. Misalnya, penjual makanan ringan yang berjualan di Ujung Timur tidak akan pernah melakukan bisnis di Barat bahkan jika ada permintaan yang harus dipenuhi dan lebih banyak uang yang harus dihasilkan, karena sangat mungkin seorang penjual makanan ringan sudah melayani daerah tersebut dengan perlindungan berbayar dan akan memiliki hak untuk mengusir pesaing."
}
return config
